(function() {
    const COOKIE_PREFERENCE_KEY = 'cookie_preferences';

    function checkCookiePreferences() {
        const preferences = localStorage.getItem(COOKIE_PREFERENCE_KEY);
        if (!preferences) {
            const container = document.getElementById('cookie-banner-container');
            if (container) {
                container.classList.add('show-banner');
            }
        }
    }

    window.acceptAllCookies = function() {
        const preferences = {
            essential: true,
            analytics: true,
            marketing: true,
            timestamp: new Date().getTime()
        };
        savePreferences(preferences);
    }

    window.rejectNonEssentialCookies = function() {
        const preferences = {
            essential: true,
            analytics: false,
            marketing: false,
            timestamp: new Date().getTime()
        };
        savePreferences(preferences);
    }

    window.saveCustomSettings = function() {
        const analytics = document.getElementById('analytics-cookies-toggle').checked;
        const marketing = document.getElementById('marketing-cookies-toggle').checked;

        const preferences = {
            essential: true,
            analytics: analytics,
            marketing: marketing,
            timestamp: new Date().getTime()
        };
        savePreferences(preferences);
    }

    function savePreferences(preferences) {
        localStorage.setItem(COOKIE_PREFERENCE_KEY, JSON.stringify(preferences));
        const container = document.getElementById('cookie-banner-container');
        if (container) {
            container.classList.remove('show-banner');
            // Small delay to allow fade out if desired, or just hide immediately
            container.style.display = 'none';
        }
        console.log('Cookie preferences saved:', preferences);
        applyCookiePreferences(preferences);
    }

    function applyCookiePreferences(preferences) {
        // Placeholder: Here you would enable/disable Google Analytics, etc.
        if (preferences.analytics) {
            console.log('Enabling Analytics scripts...');
        }
        if (preferences.marketing) {
            console.log('Enabling Marketing scripts...');
        }
    }

    window.toggleSettings = function() {
        const mainView = document.getElementById('main-banner-view');
        const settingsView = document.getElementById('settings-view');

        if (settingsView.style.display === 'block') {
            mainView.style.display = 'block';
            settingsView.style.display = 'none';
        } else {
            mainView.style.display = 'none';
            settingsView.style.display = 'block';
        }
    }

    // Initialize
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', checkCookiePreferences);
    } else {
        checkCookiePreferences();
    }
})();

// nav-profile:start
// Navbar profile menu: guest click goes to login (and back), signed-in click opens the menu. Also closes search results.
(function () {
    function cookie(name) {
        var m = document.cookie.match(new RegExp("(?:^|; )" + name + "=([^;]*)"));
        return m ? decodeURIComponent(m[1]) : "";
    }
    function authState() {
        var u = cookie("user_id");
        return u && u !== "Guest" ? "user" : "guest";
    }
    document.documentElement.setAttribute("data-auth", authState());

    function loginUrl() {
        var path = window.location.pathname;
        if (/^\/(login|register|forgot-password|update-password)/.test(path)) return "/login";
        return "/login?redirect-to=" + encodeURIComponent(path + window.location.search);
    }
    function fill(menu) {
        var name = (cookie("full_name") || "").trim();
        var email = cookie("user_id");
        var nameEl = menu.querySelector(".nav-profile__name p");
        var emailEl = menu.querySelector(".nav-profile__email p");
        var initialEl = menu.querySelector(".nav-profile__initial p");
        if (nameEl) nameEl.textContent = name || email || "My account";
        if (emailEl) emailEl.textContent = email || "";
        if (initialEl) initialEl.textContent = ((name || email || "U").trim().charAt(0) || "U").toUpperCase();
    }
    function logout(e) {
        e.preventDefault();
        var token = (window.frappe && window.frappe.csrf_token) || "";
        fetch("/api/method/logout", {
            method: "POST",
            credentials: "same-origin",
            headers: { "X-Frappe-CSRF-Token": token, "X-Requested-With": "XMLHttpRequest", "Content-Type": "application/json" }
        }).finally(function () {
            var stay = !/^\/(profile|checkout)/.test(window.location.pathname);
            if (stay) window.location.reload();
            else window.location.href = "/home";
        });
    }
    function bindProfile() {
        var wrap = document.getElementById("profile-menu");
        var btn = document.getElementById("profile-open-button");
        if (wrap && btn) {
            wrap.setAttribute("data-auth", authState());
            fill(wrap);
            var setOpen = function (open) {
                wrap.classList.toggle("is-open", open);
                btn.setAttribute("aria-expanded", open ? "true" : "false");
            };
            btn.addEventListener("click", function (e) {
                e.stopPropagation();
                if (authState() === "guest") { window.location.href = loginUrl(); return; }
                setOpen(!wrap.classList.contains("is-open"));
            });
            document.addEventListener("click", function (e) { if (!wrap.contains(e.target)) setOpen(false); });
            document.addEventListener("keydown", function (e) { if (e.key === "Escape") setOpen(false); });
        }
        document.querySelectorAll(".js-logout").forEach(function (el) { el.addEventListener("click", logout); });
        document.querySelectorAll(".js-auth-guest").forEach(function (el) {
            if (el.getAttribute("href") === "/login") el.setAttribute("href", loginUrl());
        });
    }
    function bindSearchClose() {
        function hideAll() {
            document.querySelectorAll("#product_search").forEach(function (box) { box.style.display = "none"; });
        }
        document.addEventListener("click", function (e) {
            document.querySelectorAll("#product_search").forEach(function (box) {
                var holder = box.parentElement;
                if (holder && !holder.contains(e.target)) box.style.display = "none";
            });
        });
        document.addEventListener("keydown", function (e) { if (e.key === "Escape") hideAll(); });
    }
    function init() { bindProfile(); bindSearchClose(); }
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
    else init();
})();
// nav-profile:end

// footer-accordion:start
// Mobile footer: link groups become collapsible rows. Desktop layout is untouched (wrappers use display: contents).
(function () {
    function findFooter() {
        var anchor = Array.prototype.find.call(document.querySelectorAll("a"), function (a) {
            return a.textContent.trim() === "Blind Components";
        });
        if (!anchor || !anchor.parentElement || !anchor.parentElement.parentElement) return null;
        var cols = anchor.parentElement.parentElement;
        var inner = cols.parentElement;
        var wrap = inner && inner.parentElement;
        var root = wrap && wrap.parentElement;
        if (!root) return null;
        return { cols: cols, inner: inner, root: root, logo: wrap.firstElementChild, news: cols.nextElementSibling };
    }

    function mark(parts) {
        parts.root.classList.add("ft-root");
        parts.inner.classList.add("ft-inner");
        parts.cols.classList.add("ft-cols");
        if (parts.logo && parts.logo !== parts.inner) parts.logo.classList.add("ft-logo");
        if (parts.news) {
            parts.news.classList.add("ft-news");
            if (parts.news.lastElementChild) parts.news.lastElementChild.classList.add("ft-social");
        }
    }

    function buildGroups(cols) {
        Array.prototype.slice.call(cols.children).forEach(function (col) {
            var group = null, inner = null;
            Array.prototype.slice.call(col.children).forEach(function (el) {
                if (el.tagName === "H4") {
                    group = document.createElement("div");
                    group.className = "ft-acc";
                    var panel = document.createElement("div");
                    panel.className = "ft-acc__panel";
                    inner = document.createElement("div");
                    inner.className = "ft-acc__inner";
                    panel.appendChild(inner);
                    col.insertBefore(group, el);
                    group.appendChild(el);
                    group.appendChild(panel);
                    el.classList.add("ft-acc__head");
                    el.setAttribute("role", "button");
                    el.setAttribute("tabindex", "0");
                    el.setAttribute("aria-expanded", "false");
                } else if (inner) {
                    inner.appendChild(el);
                }
            });
        });
    }

    function bind(cols) {
        var mq = window.matchMedia("(max-width: 767px)");
        function toggle(group) {
            if (!mq.matches) return;
            var open = !group.classList.contains("is-open");
            cols.querySelectorAll(".ft-acc.is-open").forEach(function (g) {
                g.classList.remove("is-open");
                g.firstElementChild.setAttribute("aria-expanded", "false");
            });
            if (open) {
                group.classList.add("is-open");
                group.firstElementChild.setAttribute("aria-expanded", "true");
            }
        }
        cols.querySelectorAll(".ft-acc__head").forEach(function (head) {
            head.addEventListener("click", function () { toggle(head.parentElement); });
            head.addEventListener("keydown", function (e) {
                if (e.key === "Enter" || e.key === " ") { e.preventDefault(); toggle(head.parentElement); }
            });
        });
    }

    function init() {
        var parts = findFooter();
        if (!parts || parts.cols.dataset.ftReady) return;
        parts.cols.dataset.ftReady = "1";
        mark(parts);
        buildGroups(parts.cols);
        bind(parts.cols);
    }

    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
    else init();
})();
// footer-accordion:end

style:
body{
  background: #fff !important;
}
:root {
  --brand-yellow: var(--primary-color-hover);
  background: #fff !important;
}
.navbar {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background: transparent;
    transition: background-color .3s ease, box-shadow .3s ease;
    z-index: 1000;
}

/* Scrolled state */
.navbar.scrolled {
    background: #fff;
    box-shadow: 0 4px 20px rgba(0,0,0,.08);
}

/* Links */
.navbar a,
.navbar p,
.navbar span {
    color: #fff;
    transition: color .3s ease;
}

.navbar.scrolled a,
.navbar.scrolled p,
.navbar.scrolled span {
    color: #000;
}

/* SVG icons */
.navbar svg {
    transition: all .3s ease;
}

@media (min-width: 992px) {
    .navbar #cart-open-button svg path,
    .navbar svg circle {
        stroke: #fff;
    }
}

.navbar.scrolled #cart-open-button svg path,
.navbar.scrolled svg circle {
    stroke: #000;
}

/* If your logo is an image you can leave it alone */
.navbar img {
    transition: opacity .3s;
}
input:focus,
input[type]:focus,
textarea:focus,
select:focus {
  outline: none;

  --tw-ring-offset-shadow: none;
  --tw-ring-shadow: none;
  --tw-ring-color: transparent;

  border-color: var(--brand-yellow);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--primary-color) 35%, transparent);
}


input[type="checkbox"],
input[type="radio"] {
  accent-color: var(--primary-color-hover);
  color: var(--primary-color-hover);
}
/* Remove default styles */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 6px;
  background: transparent;
  cursor: pointer;
}

/* =========================
   CHROME / EDGE / SAFARI
   ========================= */

/* Track */
input[type="range"]::-webkit-slider-runnable-track {
  height: 6px;
  background: #e5e5e5;
  border-radius: 999px;
}

/* Filled part */
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  height: 16px;
  width: 16px;
  background: var(--brand-yellow);
  border-radius: 50%;
  margin-top: -5px;
  box-shadow: -1000px 0 0 1000px var(--brand-yellow);
}

/* =========================
   FIREFOX
   ========================= */

input[type="range"]::-moz-range-track {
  height: 6px;
  background: #e5e5e5;
  border-radius: 999px;
}

input[type="range"]::-moz-range-progress {
  height: 6px;
  background: var(--brand-yellow);
  border-radius: 999px;
}

input[type="range"]::-moz-range-thumb {
  height: 16px;
  width: 16px;
  background: var(--brand-yellow);
  border-radius: 50%;
  border: none;
}

/* =========================
   FOCUS STATE
   ========================= */

input[type="range"]:focus-visible {
  outline: none;
}

input[type="range"]:focus-visible::-webkit-slider-thumb {
  box-shadow:
    -1000px 0 0 1000px var(--brand-yellow),
    0 0 0 4px color-mix(in srgb, var(--primary-color) 40%, transparent);
}

/* Card */
.product-card {
    position: relative;
    overflow: hidden;
	min-height: 400px;
	height: 100%;
}

/* Image */
.product-image {
    position: relative;
    z-index: 1;
    max-height: 250px;
}

.product-image img{
    height: 100%;
}

/* Content area */
.product-content {
    position: absolute;
    bottom: 0;
    left: 0;
    width: 100%;
    padding: 16px;
    background: var(--warm-bg-color);
    z-index: 2;
  	padding: 10px;
    transform: translateY(30px);
    transition: transform 0.4s ease;
}

/* Title & price */
.product-title,
.product-price {
    transition: transform 0.4s ease;
}

/* Button hidden on load */
.add-variants-cart,
.add-to-cart {
    opacity: 0;
    transform: translateY(30px);
    pointer-events: none;
    transition: opacity 0.3s ease, transform 0.4s ease;
}

/* Hover effects */
.product-card:hover .product-content {
    transform: translateY(-20px);
}

.product-card:hover .add-variants-cart,
.product-card:hover .add-to-cart {
    opacity: 1;
    transform: translateY(10px);
    pointer-events: auto;
}

.fade-3d {
  opacity: 0;
  transform-style: preserve-3d;
  transform:
    translate3d(0px, 32px, -40px) 
    scale3d(0.99, 0.99, 1)
    rotateX(6deg)               
    rotateY(0deg)
    rotateZ(0deg)
    skew(0deg, 0deg);

  transition:
    transform 0.9s cubic-bezier(0.25, 0.46, 0.45, 0.94),
    opacity 0.6s ease-out;
  will-change: transform, opacity;
}

.fade-3d.from-bottom {
  transform:
    translate3d(0px, 70px, -140px)
    scale3d(0.97, 0.97, 0.97)
    rotateX(22deg)
    rotateY(0deg)
    rotateZ(0deg)
    skew(0deg, 0deg);
}

.fade-3d.from-top {
  transform: translate3d(0, -60px, -80px) rotateX(-18deg);
}

.fade-3d.from-left {
  transform: translate3d(-60px, 0, -80px) rotateY(-18deg);
}

.fade-3d.from-right {
  transform: translate3d(60px, 0, -80px) rotateY(18deg);
}
.fade-3d.in {
  opacity: 1;
  transform:
    translate3d(0px, 0px, 0px)
    scale3d(1, 1, 1)
    rotateX(0deg)
    rotateY(0deg)
    rotateZ(0deg)
    skew(0deg, 0deg);
  transform-style: preserve-3d;
}

