}

.auth-page :is(section, div):has(.auth-grid):not(.auth-grid) :is(section, div):has(.auth-grid):not(.auth-grid) { padding: 0; }

/* ---------- titles ---------- */
.auth-page .auth-title, .auth-page .auth-title p {
