/* ---------- cards ---------- */
.auth-page .auth-card {
    box-sizing: border-box; display: flex; flex-direction: column; align-items: stretch; justify-content: flex-start; gap: 16px;
    width: 100%; max-width: none; height: auto; margin: 0; padding: 32px; overflow: visible;
