.auth-page .auth-card__head > :first-child, .auth-page .auth-card__head > :first-child p { font-size: 22px; font-weight: 700; line-height: 1.3; color: var(--a-navy); }
.auth-page .auth-card__head > :not(:first-child), .auth-page .auth-card__head > :not(:first-child) p { font-size: 14px; font-weight: 400; line-height: 1.5; color: var(--a-muted); }
