/* ---------- controls ---------- */
.auth-page input:not([type="checkbox"]):not([type="radio"]), .auth-page select, .auth-page textarea {
    box-sizing: border-box; width: 100%; min-width: 0; height: 48px; margin: 0; padding: 0 14px;
    font: inherit; font-size: 15px; color: var(--a-ink); background-color: #fff;
